#!/usr/bin/env bash
#
# Uploads dist packages on Chevah's server, then shows final links.
# To be used through GitHub actions.

set -o nounset
set -o errexit
set -o pipefail

source build.conf

root_link="https://$UPLOAD_SERVER:20443/$TARGET_DEPLOY"

# The build/publish_dist_sftp_batch file is generated by the build process.
# The private key comes from GitHub Secrets through the configured workflow.

target_dir="/${TARGET_DEPLOY}/${PYTHIA_RELEASE}/"
batch_file="${BUILD_DIR}/sftp.batch"
ls -al ${DIST_DIR}
echo "> Uploading to ${target_dir}"
echo "-mkdir ${target_dir}" > "${batch_file}"
echo "mput ${DIST_DIR}/python-*.tar.gz ${target_dir}" >> "${batch_file}"

sftp_opts=(-P 10022 -b ${batch_file} -o IdentityFile=priv_key \
    -o StrictHostKeyChecking=yes)

OS="$(uname -s)"
case "$OS" in
    MINGW*|MSYS*)
        # To use an RSA key, upstream SFTP is installed through GitHub actions.
        sftp_cmd="/c/Progra~1/OpenSSH-Win64/sftp.exe"
        ;;
    *)
        sftp_cmd="sftp"
        ;;
esac

"$sftp_cmd" "${sftp_opts[@]}" "$UPLOAD_USER"@"$UPLOAD_SERVER"
